import{b as d,O as r,g as a,j as e}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"缺陷记录","description":"","frontmatter":{},"headers":[],"relativePath":"testing/appendix/bug-record/index.md","filePath":"测试理论与实践/7.附录：模板与核心概念/03.缺陷记录.md","lastUpdated":1781625968000}'),o={name:"testing/appendix/bug-record/index.md"};function n(s,t,h,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="缺陷记录" tabindex="-1">缺陷记录 <a class="header-anchor" href="#缺陷记录" aria-label="Permalink to &quot;缺陷记录&quot;">​</a></h1><blockquote><p>Bug 写得清楚，开发改得飞快；写得含糊，双方来回猜谜浪费半天。缺陷记录是测试和开发之间最重要的沟通媒介。</p></blockquote><h2 id="缺陷记录是什么" tabindex="-1">缺陷记录是什么 <a class="header-anchor" href="#缺陷记录是什么" aria-label="Permalink to &quot;缺陷记录是什么&quot;">​</a></h2><p>缺陷记录（Bug Report）是测试人员发现 Bug 后提交的标准化文档，核心目的只有一个：<strong>让开发人员能复现、能定位、能修复</strong>。</p><p>和<a href="/testing/execution/bug-management.html">缺陷管理</a>不同——缺陷管理讲的是 Bug 的一生怎么流转（提交→审核→修复→验证→关闭），缺陷记录讲的是<strong>写 Bug 的时候每条字段怎么填</strong>。一个管流程，一个管格式。</p><h2 id="核心要素" tabindex="-1">核心要素 <a class="header-anchor" href="#核心要素" aria-label="Permalink to &quot;核心要素&quot;">​</a></h2><p>先看全景，一条完整的缺陷记录包含 9 个核心要素：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>要素</th><th>回答的问题</th><th>一句话说明</th><th>填写示例</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>缺陷编号</strong></td><td>这是哪个 Bug？</td><td>唯一标识，全流程追溯</td><td>BUG-20240615-001</td></tr><tr><td style="text-align:center;">2</td><td><strong>缺陷标题</strong></td><td>一句话说清什么问题？</td><td>模块 + 条件 + 现象</td><td>登录页：正确账号密码点击登录后页面白屏</td></tr><tr><td style="text-align:center;">3</td><td><strong>严重程度</strong></td><td>影响有多大？</td><td>测试人员根据对系统的影响判定</td><td>Critical</td></tr><tr><td style="text-align:center;">4</td><td><strong>优先级</strong></td><td>多快必须修？</td><td>产品/项目经理根据业务紧急度判定</td><td>P0</td></tr><tr><td style="text-align:center;">5</td><td><strong>重现步骤</strong></td><td>怎么复现？</td><td>别人照着做一定看到同样现象</td><td>见下方详述</td></tr><tr><td style="text-align:center;">6</td><td><strong>环境信息</strong></td><td>在什么环境上发现的？</td><td>OS、浏览器、版本、分辨率</td><td>Windows 11 / Chrome 125 / 1920×1080</td></tr><tr><td style="text-align:center;">7</td><td><strong>期望 vs 实际</strong></td><td>期望怎样 vs 实际怎样？</td><td>不写期望的 Bug 报告是半成品</td><td>期望：跳转首页 / 实际：页面白屏</td></tr><tr><td style="text-align:center;">8</td><td><strong>附件</strong></td><td>有什么证据？</td><td>截图、录屏、日志、接口响应</td><td>附白屏截图 + Console 报错日志</td></tr><tr><td style="text-align:center;">9</td><td><strong>备注</strong></td><td>有什么要补充的？</td><td>发现频率、临时绕过方案、关联 Bug</td><td>100% 必现</td></tr></tbody></table><blockquote><p>9 个要素中，<strong>重现步骤</strong>是最关键的——别人照着做能复现，Bug 就已经解决了一半。<strong>期望 vs 实际</strong>决定了开发有没有改对方向。</p></blockquote><hr><h2 id="各要素详解" tabindex="-1">各要素详解 <a class="header-anchor" href="#各要素详解" aria-label="Permalink to &quot;各要素详解&quot;">​</a></h2><h3 id="_1-缺陷编号" tabindex="-1">1. 缺陷编号 <a class="header-anchor" href="#_1-缺陷编号" aria-label="Permalink to &quot;1. 缺陷编号&quot;">​</a></h3><p>唯一标识，推荐格式：<code>BUG-日期-序号</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例：BUG-20240615-001  /  BUG-20240615-002</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规则：</span></span>
<span class="line"><span>- 前缀统一用 BUG</span></span>
<span class="line"><span>- 日期用 YYYYMMDD（发现日期）</span></span>
<span class="line"><span>- 序号三位数，同一天内递增</span></span></code></pre></div><blockquote><p>编号一旦确定不要改——测试用例、测试报告、代码 commit 都会引用它。</p></blockquote><h3 id="_2-缺陷标题" tabindex="-1">2. 缺陷标题 <a class="header-anchor" href="#_2-缺陷标题" aria-label="Permalink to &quot;2. 缺陷标题&quot;">​</a></h3><p><strong>公式：模块 + 条件 + 现象</strong>。让开发扫一眼标题就知道什么事。</p><table tabindex="0"><thead><tr><th>坏标题</th><th>好标题</th><th>差在哪</th></tr></thead><tbody><tr><td>&quot;登录有问题&quot;</td><td>登录页：正确账号密码点击登录后页面白屏</td><td>没说具体现象</td></tr><tr><td>&quot;支付挂了&quot;</td><td>支付回调：支付宝支付成功后回调超时，订单状态未更新</td><td>没说哪个环节、什么表现</td></tr><tr><td>&quot;列表不对&quot;</td><td>订单列表：筛选&quot;待发货&quot;后列表显示为空，实际有 3 条待发货订单</td><td>没说期望和实际</td></tr></tbody></table><h3 id="_3-严重程度" tabindex="-1">3. 严重程度 <a class="header-anchor" href="#_3-严重程度" aria-label="Permalink to &quot;3. 严重程度&quot;">​</a></h3><p>测试人员根据 Bug <strong>对系统功能的影响</strong>判定，不因业务紧急度改变：</p><table tabindex="0"><thead><tr><th>级别</th><th>标签</th><th>判定标准</th><th>例子</th></tr></thead><tbody><tr><td><strong>Critical</strong></td><td>紧急</td><td>系统崩溃、数据丢失、核心功能完全不可用</td><td>支付接口挂了，用户无法付款</td></tr><tr><td><strong>High</strong></td><td>高级</td><td>核心功能严重受损，但有临时绕过方案</td><td>某个支付方式不可用，用户可切换到其他方式</td></tr><tr><td><strong>Medium</strong></td><td>中级</td><td>功能部分异常，不影响核心流程</td><td>订单详情页的优惠金额显示错误</td></tr><tr><td><strong>Low</strong></td><td>低级</td><td>轻微瑕疵，不影响使用</td><td>按钮颜色偏了 1px、一个错别字</td></tr></tbody></table><h3 id="_4-优先级" tabindex="-1">4. 优先级 <a class="header-anchor" href="#_4-优先级" aria-label="Permalink to &quot;4. 优先级&quot;">​</a></h3><p>产品经理或项目经理根据<strong>业务紧急度</strong>判定——什么时候必须修：</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>什么时候修</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>阻塞上线，必须立即修复</td><td>现在、马上、不能等</td></tr><tr><td><strong>P1</strong></td><td>当前版本必须修</td><td>本次迭代内</td></tr><tr><td><strong>P2</strong></td><td>应该修，但不阻塞上线</td><td>下次迭代</td></tr><tr><td><strong>P3</strong></td><td>锦上添花</td><td>有空再说</td></tr></tbody></table><blockquote><p><strong>严重程度 ≠ 优先级</strong>。一个首页 Logo 歪了 2px，严重性 Low，但明天是品牌发布会，优先级就是 P0。反过来，一个导致数据丢失的 Bug 严重性 Critical，优先级必然是 P0。详细说明见<a href="/testing/execution/bug-management.html">缺陷管理</a>中的优先级 vs 严重性章节。</p></blockquote><h3 id="_5-重现步骤" tabindex="-1">5. 重现步骤 <a class="header-anchor" href="#_5-重现步骤" aria-label="Permalink to &quot;5. 重现步骤&quot;">​</a></h3><p><strong>这是整份 Bug 报告的灵魂</strong>。写步骤时假设看的人完全不了解这个功能：</p><table tabindex="0"><thead><tr><th>写法</th><th>步骤</th></tr></thead><tbody><tr><td>❌ 模糊</td><td>&quot;登录一下就能看到 Bug&quot;</td></tr><tr><td>✅ 精确</td><td>1. 打开登录页 <a href="https://example.com/login" target="_blank" rel="noreferrer">https://example.com/login</a></td></tr><tr><td></td><td>2. 输入邮箱 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a></td></tr><tr><td></td><td>3. 输入密码 Abc@123</td></tr><tr><td></td><td>4. 点击&quot;登录&quot;按钮</td></tr><tr><td></td><td>5. 观察页面——页面变为空白，URL 无变化</td></tr></tbody></table><blockquote><p>写步骤的口诀：<strong>哪里开始、每一步做什么、最后看到什么</strong>。如果有人照着你的步骤操作却没看到 Bug，这条步骤需要重写。</p></blockquote><h3 id="_6-环境信息" tabindex="-1">6. 环境信息 <a class="header-anchor" href="#_6-环境信息" aria-label="Permalink to &quot;6. 环境信息&quot;">​</a></h3><p>同一个 Bug 在 Chrome 上有、Safari 上没有——不写环境，开发在 Safari 上试了半天说&quot;我这没问题啊&quot;。</p><table tabindex="0"><thead><tr><th>类型</th><th>必填项</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 11 23H2 / macOS 14.5 / iOS 17.5</td></tr><tr><td>浏览器</td><td>Chrome 125.0 / Safari 17.5 / Firefox 126.0</td></tr><tr><td>屏幕分辨率</td><td>1920×1080 / 2560×1440</td></tr><tr><td>设备型号</td><td>iPhone 15 Pro / 小米 14</td></tr><tr><td>App 版本</td><td>v2.0.1-beta.3</td></tr><tr><td>网络环境</td><td>WiFi / 4G / 内网 VPN</td></tr></tbody></table><blockquote><p>至少写清楚 OS + 浏览器 + 版本号。移动端加设备型号和 App 版本。</p></blockquote><h3 id="_7-期望-vs-实际" tabindex="-1">7. 期望 vs 实际 <a class="header-anchor" href="#_7-期望-vs-实际" aria-label="Permalink to &quot;7. 期望 vs 实际&quot;">​</a></h3><p>只说&quot;有问题&quot;是废话，必须说清&quot;期望怎样，实际怎样&quot;：</p><table tabindex="0"><thead><tr><th>写法</th><th>期望</th><th>实际</th></tr></thead><tbody><tr><td>❌ 只写实际</td><td>—</td><td>点了登录页面白屏</td></tr><tr><td>✅ 期望 + 实际</td><td>点击登录后跳转到首页 <code>/home</code></td><td>点击登录后页面变为空白，URL 停留在 <code>/login</code></td></tr></tbody></table><h3 id="_8-附件" tabindex="-1">8. 附件 <a class="header-anchor" href="#_8-附件" aria-label="Permalink to &quot;8. 附件&quot;">​</a></h3><p>有证据的 Bug 报告和没证据的，处理效率差三倍：</p><table tabindex="0"><thead><tr><th>附件类型</th><th>适用场景</th><th>工具</th></tr></thead><tbody><tr><td><strong>截图</strong></td><td>界面异常、数据显示错误</td><td>系统截图工具</td></tr><tr><td><strong>录屏</strong></td><td>操作流程型 Bug、偶发 Bug</td><td>Loom / Screenity / QuickTime</td></tr><tr><td><strong>Console 日志</strong></td><td>前端报错</td><td>F12 → Console → 右键 Save as</td></tr><tr><td><strong>网络请求</strong></td><td>接口报错、超时</td><td>F12 → Network → 右键 Save all as HAR</td></tr><tr><td><strong>接口响应体</strong></td><td>后端返回数据异常</td><td>复制完整的 Request / Response JSON</td></tr></tbody></table><blockquote><p>偶发 Bug 一定要录屏。开发最怕的就是&quot;偶发&quot;——没有录屏，偶发 = 不存在。</p></blockquote><h3 id="_9-备注" tabindex="-1">9. 备注 <a class="header-anchor" href="#_9-备注" aria-label="Permalink to &quot;9. 备注&quot;">​</a></h3><p>补充有助于开发排查的信息：</p><table tabindex="0"><thead><tr><th>场景</th><th>备注内容</th></tr></thead><tbody><tr><td>偶发 Bug</td><td>&quot;复现概率约 30%，清理缓存后再试可能提高复现率&quot;</td></tr><tr><td>有临时绕过方案</td><td>&quot;使用 Firefox 浏览器可正常操作，仅 Chrome 有问题&quot;</td></tr><tr><td>疑似关联其他 Bug</td><td>&quot;可能与 BUG-20240610-012 同根因，现象相似&quot;</td></tr><tr><td>建议修复方向</td><td>&quot;怀疑是支付回调的幂等处理没做好，重复回调导致状态异常&quot;</td></tr></tbody></table><hr><h2 id="写好缺陷记录的四条铁律" tabindex="-1">写好缺陷记录的四条铁律 <a class="header-anchor" href="#写好缺陷记录的四条铁律" aria-label="Permalink to &quot;写好缺陷记录的四条铁律&quot;">​</a></h2><h3 id="_1-一个-bug-只写一个问题" tabindex="-1">1. 一个 Bug 只写一个问题 <a class="header-anchor" href="#_1-一个-bug-只写一个问题" aria-label="Permalink to &quot;1. 一个 Bug 只写一个问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>❌ 一个 Bug 塞多个问题</th><th>✅ 拆成多个</th></tr></thead><tbody><tr><td>标题：登录页有问题</td><td>BUG-001：登录后页面白屏</td></tr><tr><td>描述里又写了密码框样式错位，又写了验证码收不到</td><td>BUG-002：密码框 focus 时边框颜色不对</td></tr><tr><td></td><td>BUG-003：验证码点击&quot;发送&quot;后 30 秒才收到</td></tr></tbody></table><p>拆开后每个 Bug 独立指派、独立修复、独立验证。</p><h3 id="_2-步骤要能-100-复现" tabindex="-1">2. 步骤要能 100% 复现 <a class="header-anchor" href="#_2-步骤要能-100-复现" aria-label="Permalink to &quot;2. 步骤要能 100% 复现&quot;">​</a></h3><p>写步骤时假设开发<strong>完全没碰过这个功能</strong>。如果某个 Bug 只有你知道怎么触发、别人复现不了——这条步骤不合格。</p><h3 id="_3-严重程度如实报-优先级让产品定" tabindex="-1">3. 严重程度如实报，优先级让产品定 <a class="header-anchor" href="#_3-严重程度如实报-优先级让产品定" aria-label="Permalink to &quot;3. 严重程度如实报，优先级让产品定&quot;">​</a></h3><p>测试人员容易犯的错：觉得某个 Bug &quot;不重要&quot;就自己把优先级降到 P3。严重程度你来定（技术影响），优先级让产品来定（业务影响）。</p><h3 id="_4-截图要带标注" tabindex="-1">4. 截图要带标注 <a class="header-anchor" href="#_4-截图要带标注" aria-label="Permalink to &quot;4. 截图要带标注&quot;">​</a></h3><p>一张没标注的截图，开发要花 10 秒找&quot;问题在哪&quot;。一张圈了红框、画了箭头的截图，开发一眼就看到了。</p><hr><h2 id="缺陷记录评审检查单" tabindex="-1">缺陷记录评审检查单 <a class="header-anchor" href="#缺陷记录评审检查单" aria-label="Permalink to &quot;缺陷记录评审检查单&quot;">​</a></h2><p>缺陷提交前，自己先过一遍：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>检查点</th><th>通过标准</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>可复现</strong></td><td>换个人照着步骤操作，能 100% 看到同样现象</td></tr><tr><td style="text-align:center;">2</td><td><strong>一个 Bug 一个点</strong></td><td>没有塞多个不相关的问题</td></tr><tr><td style="text-align:center;">3</td><td><strong>期望明确</strong></td><td>写清楚了操作后期望看到什么</td></tr><tr><td style="text-align:center;">4</td><td><strong>环境完整</strong></td><td>OS + 浏览器 + 版本号齐全</td></tr><tr><td style="text-align:center;">5</td><td><strong>有证据</strong></td><td>至少有一张截图或录屏</td></tr><tr><td style="text-align:center;">6</td><td><strong>严重程度合理</strong></td><td>按定义分级，没有情绪化拔高或低调处理</td></tr></tbody></table><hr><h2 id="常见坑点" tabindex="-1">常见坑点 <a class="header-anchor" href="#常见坑点" aria-label="Permalink to &quot;常见坑点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>后果</th><th>正确做法</th></tr></thead><tbody><tr><td>标题只有&quot;XX 有问题&quot;</td><td>开发不知道什么事，先花 5 分钟找你问清楚</td><td>模块 + 条件 + 现象</td></tr><tr><td>不写期望结果</td><td>开发按自己的理解修完了，但不是你想要的效果</td><td>每份 Bug 报告必须有&quot;期望 vs 实际&quot;</td></tr><tr><td>环境信息缺失</td><td>开发复现不了，标记&quot;无法复现&quot;打回来</td><td>OS + 浏览器 + 版本至少这三项</td></tr><tr><td>多个问题挤在一个 Bug 里</td><td>修了一个忘了另一个，关闭后又被重开</td><td>一个 Bug 一个点</td></tr><tr><td>严重程度情绪化</td><td>&quot;这 Bug 太离谱了必须 P0&quot;——实际上只影响 1 个后台报表</td><td>对照严重程度定义客观判定</td></tr></tbody></table><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>缺陷记录 9 要素：编号、标题、严重程度、优先级、重现步骤、环境、期望 vs 实际、附件、备注</li><li><strong>重现步骤</strong>是灵魂——能 100% 复现的 Bug，已经解决了一半</li><li><strong>严重程度 ≠ 优先级</strong>：严重程度是技术影响（测试定），优先级是业务紧急度（产品定）</li><li>四条铁律：一个 Bug 一个点、步骤 100% 复现、严重程度如实报、截图要标注</li><li>提 Bug 前拿评审检查单过一遍——可复现、单一、期望明确、环境完整、有证据</li></ol>`,64)])])}const c=d(o,[["render",n]]);export{b as __pageData,c as default};
